Validation Job: https://aaponprem.chrislab.dev/execution/jobs/playbook/${validate_pem.artifacts.validation_job_id}/output

extra_vars.description:
Java keystore certificate renewal requiring service restart.

Host: ${trigger.host}
Service: ${trigger.service}
Port: ${trigger.port}
Cert Type: Java Keystore
Days Remaining: ${trigger.days_remaining}
Expiry: ${trigger.expiry_date}

